// The Patchwork mark: four patches in a range of skin tones, stitched together.
// Kept in sync with public/icons (generated by scripts/make-icons.mjs).

export const LOGO_TONES = ["#f1c7a8", "#c98d64", "#8d5a3b", "#4f3226"];

export function Logo({ size = 40 }: { size?: number }) {
  const [a, b, c, d] = LOGO_TONES;
  return (
    <svg width={size} height={size} viewBox="0 0 64 64" role="img" aria-label="Patchwork logo" class="logo">
      <rect width="64" height="64" rx="16" fill="#0b6e66" />
      <rect x="11" y="11" width="19" height="19" rx="5" fill={a} />
      <rect x="34" y="11" width="19" height="19" rx="5" fill={b} />
      <rect x="11" y="34" width="19" height="19" rx="5" fill={c} />
      <rect x="34" y="34" width="19" height="19" rx="5" fill={d} />
      <path d="M32 8v48M8 32h48" stroke="#e8f6f4" stroke-width="1.6" stroke-dasharray="2.5 2.5" stroke-linecap="round" opacity="0.75" />
    </svg>
  );
}
